<?php require 'includes/core.php';require 'includes/pix.php';$u=require_user();if($u['role']==='admin')go('admin/dashboard.php');$plans=plans();$key=strtolower($_POST['plan']??$_GET['plan']??'profissional');if(!isset($plans[$key]))$key='profissional';$plan=$plans[$key];$code='SUPPORTDESK-DEMONSTRACAO-PIX-'.strtoupper($key).'-SEM-VALOR-FINANCEIRO';$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='real_pix'){
 csrf();
 if(!pix_enabled()){$error='Pix real ainda não configurado no servidor.';}
 else{
  try{
   $reference='PIX-'.strtoupper(bin2hex(random_bytes(12)));
   $resp=pix_request('POST','/v1/payments',[
     'transaction_amount'=>(float)$plan['price'],
     'description'=>'SupportDesk - Plano '.$plan['name'],
     'payment_method_id'=>'pix',
     'external_reference'=>$reference,
     'payer'=>['email'=>$u['email'],'first_name'=>$u['name']]
   ],$reference);
   $providerId=(string)($resp['id']??'');$details=$resp['point_of_interaction']['transaction_data']??[];
   $qrcode=(string)($details['qr_code']??'');$base64=(string)($details['qr_code_base64']??'');
   if(!preg_match('/^[0-9]+$/',$providerId)||$qrcode===''||!preg_match('/^[A-Za-z0-9+\/=]+$/',$base64))throw new RuntimeException('Provedor não retornou QR Code válido.');
   $ins=db()->prepare("INSERT INTO pix_orders (user_id,provider_id,reference,plan_name,amount,status,pix_code,qr_base64) VALUES (?,?,?,?,?,'pending',?,?)");
   $ins->execute([$u['id'],$providerId,$reference,$plan['name'],$plan['price'],$qrcode,$base64]);
   go('pix-pending.php?id='.db()->lastInsertId());
  }catch(Throwable $e){$error='Não foi possível gerar Pix real: '.$e->getMessage();}
 }
}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')!=='real_pix'){csrf();$method=$_POST['method']??'';$digits=preg_replace('/\D/','',(string)($_POST['number']??''));if(!in_array($method,['PIX','Cartão'],true))$error='Forma inválida.';elseif($method==='Cartão'&&(!in_array($digits,['4242424242424242','5555555555554444','378282246310005'],true)||trim($_POST['holder']??'')===''||($_POST['expiry']??'')!=='12/30'||($_POST['cvv']??'')!=='123'))$error='Use um dos cartões de teste indicados na página, validade 12/30 e CVV 123.';else{try{$pdo=db();$pdo->beginTransaction();$pdo->prepare("UPDATE subscriptions SET status='expired' WHERE user_id=? AND status='active'")->execute([$u['id']]);$s=$pdo->prepare("INSERT INTO subscriptions(user_id,plan_name,amount,status,starts_at,expires_at) VALUES(?,?,?,'active',NOW(),DATE_ADD(NOW(), INTERVAL 30 DAY))");$s->execute([$u['id'],$plan['name'],$plan['price']]);$sid=$pdo->lastInsertId();$pdo->prepare('UPDATE users SET active_plan=?,plan_expires_at=DATE_ADD(NOW(),INTERVAL 30 DAY) WHERE id=?')->execute([$plan['name'],$u['id']]);$ref='DEMO-'.strtoupper(bin2hex(random_bytes(6)));$s=$pdo->prepare("INSERT INTO payments(user_id,subscription_id,plan_name,amount,method,status,last_four,transaction_code) VALUES(?,?,?,?,?,'Aprovado',?,?)");$s->execute([$u['id'],$sid,$plan['name'],$plan['price'],$method,$method==='Cartão'?substr($digits,-4):null,$ref]);$pdo->commit();go('payment-success.php?ref='.urlencode($ref));}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error='Falha na gravação do pagamento demonstrativo. Confira o banco de dados.';}}}layout_start('Checkout',$u);?><span class="kicker">CHECKOUT · DEMONSTRAÇÃO E PIX INTEGRADO</span><h1 class="page-title">Finalizar assinatura</h1><?php if(pix_enabled()):?><div class="card" style="margin-bottom:20px"><h2>◆ Pagar com Pix real (Mercado Pago)</h2><p>Gera um QR Code de cobrança real. Seu plano só será ativado depois que o provedor confirmar o recebimento.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="action" value="real_pix"><input type="hidden" name="plan" value="<?=h($key)?>"><button class="btn" type="submit">Gerar QR Code Pix real · <?=money($plan['price'])?></button></form></div><?php else: ?><div class="notice-demo">Pix real desativado. Configure <code>MP_ACCESS_TOKEN</code> e importe <code>database/upgrade_v6.sql</code>. O pagamento abaixo é somente uma simulação.</div><?php endif;?><div class="checkout"><div class="card"><h2>Resumo do pedido</h2><p class="muted">Plano mensal selecionado</p><h2><?=h($plan['name'])?></h2><div class="price"><?=money($plan['price'])?><small> / 30 dias</small></div><hr><p>✓ Acesso à central de suporte</p><p>✓ Acompanhamento de chamados</p><p>✓ Respostas da equipe</p><div class="notice-demo"><strong>Ambiente acadêmico:</strong> QR e cartão são apenas demonstrativos. Não use dados bancários verdadeiros.</div><p><a href="<?=url('plans.php')?>">← Alterar plano</a></p></div><div class="card"><h2>Simulação para apresentação</h2><p class="muted">Simule uma transação para ativar o plano.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><form method="post" id="paymentForm"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="plan" value="<?=h($key)?>"><div class="methodgrid"><label class="method"><input type="radio" name="method" value="PIX" checked><span>◆ Pix</span></label><label class="method"><input type="radio" name="method" value="Cartão"><span>▤ Cartão</span></label></div><div id="pix"><p><strong>Escaneie o QR de demonstração</strong></p><img class="qr" src="<?=url('assets/qr/'.$key.'.png')?>" alt="QR Code demonstrativo Pix"><p class="subtle">Este QR contém texto de teste, não uma chave Pix válida.</p><div class="copycode" id="pixcode"><?=h($code)?></div><div class="actions"><button type="button" class="btn secondary" onclick="navigator.clipboard.writeText(document.getElementById('pixcode').innerText).then(()=>alert('Código demonstrativo copiado!'))">Copiar código</button></div></div><div id="card" hidden><div class="notice-demo">Ambiente de testes: use apenas os números de exemplo; nenhum cartão será cobrado.</div><div class="brand-panel"><span>Bandeira detectada</span><strong id="cardBrand" aria-live="polite">Aguardando número</strong></div><div class="test-cards"><button type="button" class="test-card" data-test-card="4242424242424242">Visa <small>•••• 4242</small></button><button type="button" class="test-card" data-test-card="5555555555554444">Mastercard <small>•••• 4444</small></button><button type="button" class="test-card" data-test-card="378282246310005">American Express <small>•••• 0005</small></button></div><?php fld('holder','Nome no cartão (teste)','text','CLIENTE TESTE');fld('number','Número do cartão','text','4242 4242 4242 4242');?><div class="split"><?php fld('expiry','Validade','text','12/30');fld('cvv','CVV','text','123');?></div></div><button class="btn block" type="submit" style="margin-top:12px">Confirmar pagamento de teste</button><p class="subtle">Ao confirmar, o sistema registra uma transação aprovada de demonstração e ativa seu plano por 30 dias.</p></form></div></div><script>const radios=document.querySelectorAll('input[name="method"]');function toggle(){let pix=document.querySelector('input[name="method"]:checked').value==='PIX';document.getElementById('pix').hidden=!pix;document.getElementById('card').hidden=pix;document.getElementById('pix').style.display=pix?'block':'none';document.getElementById('card').style.display=pix?'none':'block';document.querySelectorAll('#card input').forEach(i=>i.disabled=pix);}radios.forEach(e=>e.addEventListener('change',toggle));toggle();
const cardNumber=document.querySelector('[name=number]');const cardBrand=document.getElementById('cardBrand');
const detectBrand=(num)=>{if(/^3[47]/.test(num))return 'American Express';if(/^(5[1-5]|2(2[2-9]|[3-6]|7[01]|720))/.test(num))return 'Mastercard';if(/^4/.test(num))return 'Visa';return num.length>0?'Não identificada':'Aguardando número';};
function maskCard(){const digits=cardNumber.value.replace(/\D/g,'').slice(0,16);cardBrand.textContent=detectBrand(digits);cardNumber.value=digits.match(/.{1,4}/g)?.join(' ')||'';}
cardNumber.addEventListener('input',maskCard);document.querySelectorAll('[data-test-card]').forEach(btn=>btn.addEventListener('click',()=>{cardNumber.value=btn.dataset.testCard;maskCard();document.querySelector('[name=holder]').value='CLIENTE TESTE';document.querySelector('[name=expiry]').value='12/30';document.querySelector('[name=cvv]').value='123';cardNumber.focus();}));maskCard();</script><?php layout_end();?>